function [yout] = alg_eq(x,u)
M 	= 0.028  ;
Ta = 293    ;
La	= 230.87 ;
Va	= 22.3e-3;
ro	= 923.9  ;
Tw	= 293    ;
Lw	= 2400   ;
Lr	= 40     ;
Ar	= 0.0182 ;
Aw  = 0.0182;
Civ	= 1.6e-3;
Cpc	= 0.5e-2;
Cr 	= 0.8e-4;
rgo = 0     ;
wgc = 1.36e4;
Ps	= 6276e3 ;
Pr	= 18632e3;
vo = 1/ro   ;
R = 8.314   ;
g = 10      ;


y(1)=(x(2)*y(11)/(x(2)+x(3))         );

y(2)=(x(3)*y(11)/(x(2)+x(3))         );

y(3)=(rgo*y(10)                      );

y(4)=((R*Ta/(Va*M)+g*La/Va)*x(1)     );

y(5)=(M*y(4)/(R*Ta)                  );

y(6)=((x(2)+x(3))/(Lw*Aw)            );

y(7)=((R*Tw/M)*(x(2)/(Lw*Aw-vo*x(3))));

y(8)=(y(7) + (g/Aw)*(x(2)+x(3))      );

y(9)=(y(8) + ro*g*Lr                 );

y(10)=(Cr*sqrt(ro*(Pr-y(9)))          );

y(11)=(Cpc*sqrt(y(6)*(y(7)-Ps))*u(1)  );

y(12)=(Civ*sqrt(y(5)*(y(4)-y(8)))     );

yout=y;
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
